WITH filtered AS (SELECT id, customer_id, device, browser, started_at, country, DATE_FORMAT(started_at, 'yyyy-MM-dd') AS started_at_label FROM sessions WHERE started_at >= TO_TIMESTAMP('2023-08-07 08:00:00')), flagged AS (SELECT *, CASE WHEN started_at - LAG(started_at) OVER (PARTITION BY browser ORDER BY started_at, id) > INTERVAL 30 DAYS THEN 1 ELSE 0 END AS is_new_burst FROM filtered), sessions_sessions AS (SELECT *, SUM(is_new_burst) OVER (PARTITION BY browser ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM flagged) SELECT DATE_TRUNC('QUARTER', started_at) AS quarter_start, customer_id, AVG(is_new_burst) FILTER (WHERE device = 'mobile') AS mobile_avg_is_new_burst, ROUND(SUM(island_id) / NULLIF(COUNT(CASE WHEN browser = 'Chrome' THEN 1 END), 0), 2) AS island_id_per_chrome, AVG(island_id) FILTER (WHERE country = 'JP') AS jp_avg_island_id FROM sessions_sessions GROUP BY ROLLUP (DATE_TRUNC('QUARTER', started_at), customer_id) ORDER BY mobile_avg_is_new_burst;
